"""Parse human-friendly duration strings into seconds."""

import re


_UNITS = {"h": 3600, "m": 60, "s": 1}

_PATTERN = re.compile(r"(\d+)([hms])")


def parse_duration(text):
    """Return the whole number of seconds in strings like '1h30m', '45s', '2h'.

    Raises ValueError for anything that is not one or more (number, unit)
    pairs covering the entire input, in h/m/s order.
    """
    if not isinstance(text, str) or not text:
        raise ValueError(f"invalid duration: {text!r}")

    if not re.fullmatch(r"(?:\d+[hms])+", text):
        raise ValueError(f"invalid duration: {text!r}")

    total = 0
    position = 0
    for match in _PATTERN.finditer(text):
        if match.start() != position:
            raise ValueError(f"invalid duration: {text!r}")
        total += int(match.group(1)) * _UNITS[match.group(2)]
        position = match.end()

    return total

