"""Parse duration strings like '1h30m' into whole seconds."""

import re

_PATTERN = re.compile(r"^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$")


def parse_duration(text):
    """Return the number of whole seconds in a duration like '1h30m'."""
    if not isinstance(text, str):
        raise ValueError("invalid duration")
    match = _PATTERN.fullmatch(text)
    if not match or not any(match.groups()):
        raise ValueError(f"invalid duration: {text!r}")
    hours, minutes, seconds = match.groups()
    return int(hours) * 3600 + int(minutes or 0) * 60 + int(seconds or 0)

