import re

_TIME_PATTERN = r"(?:(\d+(?:\.\d+)?)d)?\s*(?:(\d+(?:\.\d+)?)h)?\s*(?:(\d+(?:\.\d+)?)m)?\s*(?:(\d+(?:\.\d+)?)s)?"
_UNIT_WORDS = r"(?:(\d+(?:\.\d+)?)\s*days?)?\s*(?:(\d+(?:\.\d+)?)\s*hours?)?\s*(?:(\d+(?:\.\d+)?)\s*minutes?)?\s*(?:(\d+(?:\.\d+)?)\s*seconds?)?"

_COMPACT = re.compile(r"^\s*" + _TIME_PATTERN + r"\s*$")
_SPACED = re.compile(r"^\s*" + _UNIT_WORDS + r"\s*$", re.IGNORECASE)


def _to_seconds(groups):
    d, h, m, s = groups
    d = float(d or 0)
    h = float(h or 0)
    m = float(m or 0)
    s = float(s or 0)
    total = d * 86400 + h * 3600 + m * 60 + s
    if total != int(total):
        raise ValueError("non-integer seconds")
    return int(total)


def parse_duration(text):
    text = str(text)
    match = _COMPACT.match(text)
    if match and any(match.groups()):
        return _to_seconds(match.groups())
    match = _SPACED.match(text)
    if match and any(match.groups()):
        return _to_seconds(match.groups())
    raise ValueError("invalid duration: %r" % text)


def format_duration(seconds):
    seconds = int(seconds)
    if seconds < 0:
        raise ValueError("negative duration")
    d, rem = divmod(seconds, 86400)
    h, rem = divmod(rem, 3600)
    m, s = divmod(rem, 60)
    if d == 0 and h == 0 and m == 0:
        return "%ds" % s
    parts = []
    if d:
        parts.append("%dd" % d)
    if h or parts:
        parts.append("%dh" % h)
    if parts or m:
        parts.append("%dm" % m)
    if parts or s:
        parts.append("%ds" % s)
    return "".join(parts)

